"use client";

import { useEffect, useRef, useState } from "react";
import { ArrowUpRight } from "lucide-react";
import { IconWrapper } from "./ui/icon-wrapper";

const experiences = [
  {
    period: "2023 - Present",
    title: "Python Django Full-Stack Developer",
    company: "Mystro Training",
    description:
      "Build and maintain full-stack applications using Django framework. Work closely with modern technologies including Docker, Celery, Redis, and Vue.js to implement and advocate for best practices in web development.",
    highlights: [
      "Created responsive websites with HTML, CSS, Bootstrap and JavaScript",
      "Built automation scripts with Python for workflow optimization",
      "Developed RESTful APIs with Django REST Framework",
      "Integrated payment systems including Stripe",
      "Deployed applications to cloud using Render",
    ],
    tech: ["Python", "Django", "DRF", "Docker", "Vue.js", "Redis", "Celery"],
  },
];

const education = {
  period: "2023 - 2024",
  degree: "Full-Stack Python & Web Development",
  school: "Mystro E-Learning School",
  type: "Bootcamp",
};

export function ExperienceSection() {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <section
      ref={sectionRef}
      id="experience"
      className="relative py-32 px-6 lg:px-12"
    >
      <div className="max-w-6xl mx-auto">
        {/* Section header */}
        <div
          className={`flex items-center gap-4 mb-16 transition-all duration-700 ${
            isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          <span className="font-mono text-primary text-sm">02.</span>
          <h2 className="text-2xl sm:text-3xl font-bold text-foreground">Experience</h2>
          <div className="flex-1 h-px bg-border max-w-[300px]" />
        </div>

        {/* Experience Items */}
        <div className="space-y-12">
          {experiences.map((exp, index) => (
            <div
              key={exp.title}
              className={`group grid lg:grid-cols-[200px_1fr] gap-4 lg:gap-8 p-6 -mx-6 rounded-xl transition-all duration-500 hover:bg-card/50 ${
                isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
              }`}
              style={{ transitionDelay: `${index * 100}ms` }}
            >
              {/* Period */}
              <div className="font-mono text-sm text-muted-foreground">
                {exp.period}
              </div>
              
              {/* Content */}
              <div>
                <h3 className="text-lg font-semibold text-foreground group-hover:text-primary transition-colors flex items-center gap-2">
                  {exp.title}
                  <span className="text-primary">@</span>
                  <a
                    href="#"
                    className="text-primary hover:underline underline-offset-4 inline-flex items-center gap-1"
                  >
                    {exp.company}
                    <IconWrapper className="w-4 h-4">
                      <ArrowUpRight className="w-4 h-4" />
                    </IconWrapper>
                  </a>
                </h3>
                
                <p className="mt-3 text-muted-foreground leading-relaxed">
                  {exp.description}
                </p>
                
                <ul className="mt-4 space-y-2">
                  {exp.highlights.map((highlight, i) => (
                    <li
                      key={i}
                      className="flex items-start gap-3 text-sm text-muted-foreground"
                    >
                      <span className="text-primary mt-1">{">"}</span>
                      <span>{highlight}</span>
                    </li>
                  ))}
                </ul>
                
                <div className="flex flex-wrap gap-2 mt-6">
                  {exp.tech.map((t) => (
                    <span
                      key={t}
                      className="px-3 py-1 text-xs font-mono bg-primary/10 text-primary rounded-full"
                    >
                      {t}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Education */}
        <div
          className={`mt-20 transition-all duration-700 delay-300 ${
            isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          <h3 className="font-mono text-sm text-primary mb-8">{"// Education"}</h3>
          
          <div className="group grid lg:grid-cols-[200px_1fr] gap-4 lg:gap-8 p-6 -mx-6 rounded-xl hover:bg-card/50 transition-colors">
            <div className="font-mono text-sm text-muted-foreground">
              {education.period}
            </div>
            
            <div>
              <h4 className="text-lg font-semibold text-foreground group-hover:text-primary transition-colors">
                {education.degree}
              </h4>
              <p className="text-primary mt-1">{education.school}</p>
              <span className="inline-block mt-3 px-3 py-1 text-xs font-mono bg-primary/10 text-primary rounded-full">
                {education.type}
              </span>
            </div>
          </div>
        </div>

        {/* Languages */}
        <div
          className={`mt-16 transition-all duration-700 delay-400 ${
            isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          <h3 className="font-mono text-sm text-primary mb-6">{"// Languages"}</h3>
          <div className="flex flex-wrap gap-4">
            {["Arabic (Native)", "English (Fluent)", "German (Conversational)"].map((lang) => (
              <div
                key={lang}
                className="px-4 py-2 bg-card/50 rounded-lg border border-border text-sm text-foreground"
              >
                {lang}
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
